play Type'=>'Tipo de pantalla incrustada','Enable'=>'Activar','Enable %s'=>'Activar %s','Enable %s attributes?'=>'¿Permitir atributos de %s?','Enable %s custom fields?'=>'¿Permitir campos personalizados de %s?','Enable All Styling?'=>'¿Activar todos los estilos?','Enable Archives?'=>'¿Permitir archivos?','Enable Code Editor for Formats'=>'Activar el editor de código para los formatos','Enable Comments?'=>'¿Permitir comentarios?','Enable Dev Updates?'=>'¿Activar actualizaciones de desarrollo?','Enable Event Dynamic Timeslots?'=>'¿Activar horarios dinámicos para eventos?','Enable Event Status?'=>'¿Activar el estado del evento?','Enable Event Timeslots?'=>'¿Activar horarios para eventos?','Enable Google Maps integration?'=>'¿Permitir la integración con Google Maps?','Enable No-User Booking Mode?'=>'¿Permitir el modo de reserva sin usuario?','Enable Theme Styling?'=>'¿Activar los estilos del tema?','Enable Timezone Support?'=>'¿Activar compatibilidad de zona horaria?','Enable Visual Uploader'=>'Activar el cargador visual','Enable a code/syntax highlighter when clicking on the larger formatting textbox options below, for easier editing of larger HTML parts.'=>'Activa un resaltador de código/sintaxis al hacer clic en los cuadros de texto de opciones de formato a continuación, para facilitar la edición de partes HTML más grandes.','Enable a modern visual uploader UI.'=>'Activa una interfaz de subida visual moderna.','Enable advanced fields?'=>'¿Activar opciones avanzadas?','Enable bookings?'=>'¿Permitir reservas?','Enable categories?'=>'¿Permitir categorías?','Enable custom event archetypes?'=>'¿Activar arquetipos de evento personalizados?','Enable custom ticket ordering?'=>'¿Activar la ordenación personalizada de entradas?','Enable global tables mode?'=>'¿Activar el modo de tablas global?','Enable locations?'=>'¿Permitir ubicaciones?','Enable multiple file uploads by default.'=>'Activar la subida de varios archivos por defecto.','Enable or disable each notification type. 